WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) AS prev_paid_at FROM payments), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT DATE_TRUNC('QUARTER', prev_paid_at) AS quarter_start, CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_new_burst_tier, STDDEV_SAMP(amount) AS amount_stddev, AVG(amount) FILTER (WHERE status = 'SUCCESS') AS success_avg_amount, PERCENTILE_APPROX(session_id, 0.5) AS session_id_p50 FROM sessionized GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', prev_paid_at), CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('QUARTER', prev_paid_at)), ()) HAVING amount_stddev >= 0 ORDER BY session_id_p50 DESC;
